package com.boot.compick.member.controller;
import com.boot.compick.member.dto.*;import com.boot.compick.member.service.EmailVerificationService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/email-verifications") @RequiredArgsConstructor public class EmailVerificationApiController{private final EmailVerificationService service;@PostMapping("/send") public ResponseEntity<Map<String,String>> send(@Valid @RequestBody EmailVerificationRequest r){requireSignup(r.purpose());service.send(r.email(),r.purpose());return ResponseEntity.ok(Map.of("message","인증번호를 발송했습니다."));}@PostMapping("/confirm") public ResponseEntity<Map<String,String>> confirm(@Valid @RequestBody EmailVerificationConfirmRequest r){requireSignup(r.purpose());service.confirm(r.email(),r.purpose(),r.code());return ResponseEntity.ok(Map.of("message","이메일 인증이 완료되었습니다."));}@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> badRequest(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}private void requireSignup(com.boot.compick.member.entity.VerificationPurpose purpose){if(purpose!=com.boot.compick.member.entity.VerificationPurpose.SIGN_UP)throw new IllegalArgumentException("허용되지 않은 인증 목적입니다.");}}
